import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { LEADERBOARD_SECTION_IDS, LeaderboardSectionId } from './leaderboardSections'

const teamId = window.POSTHOG_APP_CONTEXT?.current_team?.id

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpLeaderboardSectionsLogicValues {
    hiddenSectionIds: LeaderboardSectionId[]
    hiddenSections: LeaderboardSectionId[]
    isSectionVisible: (id: LeaderboardSectionId) => boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpLeaderboardSectionsLogicActions {
    showAllSections: () => {
        value: true
    }
    toggleSection: (id: LeaderboardSectionId) => {
        id: LeaderboardSectionId
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpLeaderboardSectionsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hiddenSections: (hiddenSectionIds: LeaderboardSectionId[]) => LeaderboardSectionId[]
        isSectionVisible: (hiddenSectionIds: LeaderboardSectionId[]) => (id: LeaderboardSectionId) => boolean
    }
}

export type mcpLeaderboardSectionsLogicType = MakeLogicType<
    mcpLeaderboardSectionsLogicValues,
    mcpLeaderboardSectionsLogicActions,
    Record<string, any>,
    mcpLeaderboardSectionsLogicMeta
>

export const mcpLeaderboardSectionsLogic = kea<mcpLeaderboardSectionsLogicType>([
    path(['products', 'mcp_analytics', 'frontend', 'leaderboardHome', 'mcpLeaderboardSectionsLogic']),
    actions({
        toggleSection: (id: LeaderboardSectionId) => ({ id }),
        showAllSections: true,
    }),
    reducers({
        // Stores hidden ids, so a section shipped later shows by default.
        hiddenSectionIds: [
            [] as LeaderboardSectionId[],
            { persist: true, prefix: `${teamId}__` },
            {
                toggleSection: (hidden, { id }) =>
                    hidden.includes(id) ? hidden.filter((h) => h !== id) : [...hidden, id],
                showAllSections: () => [],
            },
        ],
    }),
    selectors({
        // Persisted ids can outlive the section they named, so read them against the live list.
        hiddenSections: [
            (s) => [s.hiddenSectionIds],
            (hiddenSectionIds: LeaderboardSectionId[]): LeaderboardSectionId[] =>
                LEADERBOARD_SECTION_IDS.filter((id) => hiddenSectionIds.includes(id)),
        ],
        isSectionVisible: [
            (s) => [s.hiddenSectionIds],
            (hiddenSectionIds: LeaderboardSectionId[]) =>
                (id: LeaderboardSectionId): boolean =>
                    !hiddenSectionIds.includes(id),
        ],
    }),
    listeners(({ values, selectors }) => ({
        toggleSection: ({ id }) => {
            posthog.capture('mcp analytics dashboard section toggled', {
                section: id,
                hidden: !values.isSectionVisible(id),
            })
        },
        showAllSections: (_, __, ___, previousState) => {
            posthog.capture('mcp analytics dashboard sections reset', {
                hidden_count: selectors.hiddenSections(previousState).length,
            })
        },
    })),
    afterMount(({ values }) => {
        // Toggles only record changes; this records what each visit actually shows.
        posthog.capture('mcp analytics dashboard viewed', {
            hidden_sections: values.hiddenSections,
            hidden_count: values.hiddenSections.length,
        })
    }),
])
